  button("Usar última imagen de la sección Imagen",()->{File f=new File(getFilesDir(),"image-current.png");if(f.isFile())loadBackground(Uri.fromFile(f));else say("Todavía no hay imagen guardada en la sección Imagen.");});
  button("Guardar proyecto de trazos",()->{end();try{pending=project().toString();create("trazos.formas.json",302);}catch(Exception e){say("No se pudo preparar el proyecto.");}});button("Abrir proyecto de trazos",()->{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("*/*");i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,303);});
  text("El proyecto incluye trazos, etiquetas y tiempos. No incluye la fotografía de fondo. Evita compartir escritura o anotaciones personales sin revisarlas.");
