  button("Usar posición actual como inicio",()->{start=point;origin.setSelection(4);say("Inicio marcado sin desplazar la imagen.");});button("Marcar inicio con el próximo toque",()->{record.setChecked(false);picking=true;say("El próximo contacto marca el inicio.");});
  select("Separación del barrido",new String[]{"Fina: 20 unidades","Media: 40 unidades","Amplia: 60 unidades"},1,n->{step=new int[]{20,40,60}[n];section=-1;});
