  button("Leer recorrido completo",()->scan(-1));button("Leer siguiente fila o cuadrante",()->{section++;scan(section);});button("Volver a primera sección",()->{section=0;scan(0);});
  height=check("La imagen aportada es un mapa de alturas",false,on->{audio.stop();say("Blanco representa mayor altura relativa con más intensidad. Sólo usa esta opción con un mapa de alturas conocido. No se infiere relieve de una foto y no se expresan milímetros.");});
